      'Art': 'শিল্প',
      'As soon as possible': 'যত তাড়াতাড়ি সম্ভব',
      'Assalamu Alaikum! I came across your profile and was genuinely impressed. May I introduce myself?':
          'আসসালামু আলাইকুম! আমি আপনার প্রোফাইল জুড়ে এসেছিলাম এবং সত্যিকারের মুগ্ধ. আমি কি আমার পরিচয় দিতে পারি?',
      'Assalamu Alaikum! I was really impressed by…':
          'আসসালামু আলাইকুম! আমি সত্যিই দ্বারা প্রভাবিত ছিলাম…',
      'Assalamu Alaikum. After sincere consideration, I feel we may not be compatible. I hope you find someone truly right for you. May Allah make it easy for you. JazakAllah khair for your time.':
          'আসসালামু আলাইকুম। আন্তরিকভাবে বিবেচনা করার পরে, আমি মনে করি আমরা সামঞ্জস্যপূর্ণ নাও হতে পারে। আমি আশা করি আপনি আপনার জন্য সত্যিই সঠিক কাউকে খুঁজে পেয়েছেন। আল্লাহ আপনার জন্য সহজ করে দিন। আপনার সময়ের জন্য জাজাকাল্লাহ খাইর।',
      'Assalamu Alaikum. After thoughtful reflection, I feel this may not be the right match for us. I sincerely wish you all the best and pray that Allah blesses you with a wonderful partner. JazakAllah khair.':
          'আসসালামু আলাইকুম। চিন্তাশীল প্রতিফলনের পরে, আমি মনে করি এটি আমাদের জন্য সঠিক ম্যাচ নাও হতে পারে। আমি আন্তরিকভাবে আপনাকে শুভকামনা জানাই এবং প্রার্থনা করি যে আল্লাহ আপনাকে একটি দুর্দান্ত অংশীদার দিয়ে আশীর্বাদ করুন। জাযাকাল্লাহ খাইর।',
      'Assalamu Alaikum. I believe we share similar values. Would you be open to getting to know each other?':
          'আসসালামু আলাইকুম। আমি বিশ্বাস করি আমরা একই মান শেয়ার করি। আপনি কি একে অপরকে জানার জন্য উন্মুক্ত হবেন?',
      'Assalamu Alaikum. I have reflected on our conversations and feel it is best to close this match at this time. I have nothing but respect for you and I make dua that Allah blesses you with the best.':
          'আসসালামু আলাইকুম। আমি আমাদের কথোপকথনের প্রতিফলন করেছি এবং মনে করি এই সময়ে এই ম্যাচটি বন্ধ করাই ভাল। আপনার প্রতি আমার শ্রদ্ধা ছাড়া আর কিছুই নেই এবং আমি দোয়া করি যে আল্লাহ আপনাকে সর্বোত্তম আশীর্বাদ করুন।',
      'Assalamu Alaikum. I wanted to be honest and respectful with you. I do not think we are the right match, but I pray that Allah opens better doors for you. Wishing you all the best.':
          'আসসালামু আলাইকুম। আমি আপনার সাথে সৎ এবং শ্রদ্ধাশীল হতে চেয়েছিলাম। আমি মনে করি না যে আমরা সঠিক ম্যাচ, তবে আমি প্রার্থনা করি যে আল্লাহ আপনার জন্য আরও ভাল দরজা খুলে দিন। আপনি সব শুভ কামনা.',
      'Assalamu Alaikum. I wanted to be transparent with you rather than fade away. I do not see this progressing further, but I truly appreciate your time and wish you every happiness. May Allah bless you.':
          'আসসালামু আলাইকুম। আমি বিবর্ণ না হয়ে আপনার সাথে স্বচ্ছ হতে চেয়েছিলাম। আমি এটিকে আরও অগ্রগতি দেখতে পাচ্ছি না, তবে আমি সত্যিই আপনার সময়ের প্রশংসা করি এবং আপনাকে প্রতিটি সুখ কামনা করি। আল্লাহ আপনার মঙ্গল করুন।',
