      'Your number': 'আপনার নম্বর',
      'Your photo gallery could not be opened. Try again.':
          'আপনার ফটো গ্যালারি খোলা যাবে না. আবার চেষ্টা করুন',
      'Your photos are reviewed before your profile goes live.':
          'আপনার প্রোফাইল লাইভ হওয়ার আগে আপনার ফটো পর্যালোচনা করা হয়।',
      'Your place in Silarah is secure. We will continue the moment the network returns.':
