      'Your profile is boosted for 2 hours!':
          'আপনার প্রোফাইল 2 ঘন্টার জন্য বুস্ট করা হয়!',
      'Your profile is hidden. No one can find you.':
          'আপনার প্রোফাইল লুকানো আছে. কেউ তোমাকে খুঁজে পাবে না।',
      'Your profile will be hidden immediately. Your data will be permanently deleted after 30 days.':
          'আপনার প্রোফাইল অবিলম্বে লুকানো হবে. আপনার ডেটা 30 দিন পরে স্থায়ীভাবে মুছে ফেলা হবে।',
      'Your request has been received! We are compiling your personal data archive.':
          'আপনার অনুরোধ গৃহীত হয়েছে! আমরা আপনার ব্যক্তিগত তথ্য সংরক্ষণাগার কম্পাইল করছি.',
      'Your ward hasn\'t started any conversations yet.\nYou\'ll see their chats here when they do.':
          'আপনার ওয়ার্ড এখনো কোনো কথোপকথন শুরু করেনি।\nতারা যখন করবে তখন আপনি এখানে তাদের চ্যাট দেখতে পাবেন।',
