      'Art': 'कला',
      'As soon as possible': 'जितनी जल्दी हो सके',
      'Assalamu Alaikum! I came across your profile and was genuinely impressed. May I introduce myself?':
          'अस्सलामु अलैकुम! मैं आपकी प्रोफ़ाइल पर आया और वास्तव में प्रभावित हुआ। क्या मैं अपना परिचय दे सकता हुँ?',
      'Assalamu Alaikum! I was really impressed by…':
          'अस्सलामु अलैकुम! मैं वास्तव में इससे प्रभावित हुआ...',
      'Assalamu Alaikum. After sincere consideration, I feel we may not be compatible. I hope you find someone truly right for you. May Allah make it easy for you. JazakAllah khair for your time.':
          'अस्सलामु अलैकुम. ईमानदारी से विचार करने के बाद, मुझे लगता है कि हम संगत नहीं हो सकते हैं। मुझे आशा है कि आपको वास्तव में कोई आपके लिए सही व्यक्ति मिल जाएगा। अल्लाह आपके लिए इसे आसान बना दे. जज़ाकअल्लाह खैर आपके समय के लिए।',
      'Assalamu Alaikum. After thoughtful reflection, I feel this may not be the right match for us. I sincerely wish you all the best and pray that Allah blesses you with a wonderful partner. JazakAllah khair.':
          'अस्सलामु अलैकुम. गहन चिंतन के बाद, मुझे लगता है कि यह हमारे लिए सही मैच नहीं हो सकता है। मैं ईमानदारी से आपको शुभकामनाएं देता हूं और प्रार्थना करता हूं कि अल्लाह आपको एक अद्भुत साथी दे। जज़ाकअल्लाह खैर.',
      'Assalamu Alaikum. I believe we share similar values. Would you be open to getting to know each other?':
          'अस्सलामु अलैकुम. मेरा मानना ​​है कि हम समान मूल्य साझा करते हैं। क्या आप एक-दूसरे को जानने के लिए तैयार होंगे?',
      'Assalamu Alaikum. I have reflected on our conversations and feel it is best to close this match at this time. I have nothing but respect for you and I make dua that Allah blesses you with the best.':
          'अस्सलामु अलैकुम. मैंने हमारी बातचीत पर विचार किया है और महसूस किया है कि इस समय इस मैच को बंद कर देना ही सबसे अच्छा है। मेरे मन में आपके लिए सम्मान के अलावा कुछ नहीं है और मैं दुआ करता हूं कि अल्लाह आपको सबसे अच्छा आशीर्वाद दे।',
      'Assalamu Alaikum. I wanted to be honest and respectful with you. I do not think we are the right match, but I pray that Allah opens better doors for you. Wishing you all the best.':
          'अस्सलामु अलैकुम. मैं आपके साथ ईमानदार और सम्मानजनक रहना चाहता था। मुझे नहीं लगता कि हम सही जोड़ीदार हैं, लेकिन मैं प्रार्थना करता हूं कि अल्लाह आपके लिए बेहतर दरवाजे खोले। आपके मंगलमय होने की कामना।',
      'Assalamu Alaikum. I wanted to be transparent with you rather than fade away. I do not see this progressing further, but I truly appreciate your time and wish you every happiness. May Allah bless you.':
          'अस्सलामु अलैकुम. मैं आपके साथ फीका पड़ने के बजाय पारदर्शी होना चाहता था। मुझे नहीं लगता कि यह आगे बढ़ेगा, लेकिन मैं वास्तव में आपके समय की सराहना करता हूं और आपकी हर खुशी की कामना करता हूं। अल्लाह तुम्हें आशीर्वाद दे।',
