      '2+ years': '2+ yıl',
      '30-day grace period': '30 günlük ödemesiz süre',
      'A complete visual identity—not a color filter. Every surface, field and system control changes together.':
          'Yalnızca bir renk filtresi değil, eksiksiz bir görsel kimlik. Tüm yüzeyler, alanlar ve sistem kontrolleri birlikte değişir.',
      'A download link will be sent to your registered phone/email within 48 hours in compliance with GDPR guidelines.':
          'Kayıtlı telefonunuza/e-posta adresinize GDPR yönergelerine uygun olarak 48 saat içinde bir indirme bağlantısı gönderilecektir.',
      'A private alert when someone opens your profile':
          'Birisi profilinizi açtığında özel bildirim',
