      'As soon as possible': 'Mümkün olan en kısa sürede',
      'Assalamu Alaikum! I came across your profile and was genuinely impressed. May I introduce myself?':
          'Selamun Aleyküm! Profilinize rastladım ve gerçekten etkilendim. Kendimi tanıtabilir miyim?',
      'Assalamu Alaikum! I was really impressed by…':
          'Selamun Aleyküm! Gerçekten etkilendim…',
      'Assalamu Alaikum. After sincere consideration, I feel we may not be compatible. I hope you find someone truly right for you. May Allah make it easy for you. JazakAllah khair for your time.':
          'Selamun Aleyküm. Samimi bir değerlendirmeden sonra uyumlu olamayacağımızı hissediyorum. Umarım senin için gerçekten doğru birini bulursun. Allah işlerinizi kolaylaştırsın. Zaman ayırdığınız için JazakAllah hayr.',
      'Assalamu Alaikum. After thoughtful reflection, I feel this may not be the right match for us. I sincerely wish you all the best and pray that Allah blesses you with a wonderful partner. JazakAllah khair.':
          'Selamun Aleyküm. Düşündükten sonra bunun bizim için doğru eşleşme olmayabileceğini hissettim. Size içtenlikle başarılar diliyor ve Allah\'ın size harika bir ortak vermesini diliyorum. CezakAllah hayr.',
      'Assalamu Alaikum. I believe we share similar values. Would you be open to getting to know each other?':
          'Selamun Aleyküm. Benzer değerleri paylaştığımıza inanıyorum. Birbirinizi tanımaya açık mısınız?',
      'Assalamu Alaikum. I have reflected on our conversations and feel it is best to close this match at this time. I have nothing but respect for you and I make dua that Allah blesses you with the best.':
          'Selamun Aleyküm. Konuşmalarımızı düşündüm ve bu maçı şu anda bitirmenin en iyisi olduğunu düşünüyorum. Size saygıdan başka bir şeyim yok ve Allah\'ın sizi en iyi şekilde kutsaması için dua ediyorum.',
      'Assalamu Alaikum. I wanted to be honest and respectful with you. I do not think we are the right match, but I pray that Allah opens better doors for you. Wishing you all the best.':
          'Selamun Aleyküm. Sana karşı dürüst ve saygılı olmak istedim. Doğru eşleşme olduğumuzu düşünmüyorum ama Allah\'ın size daha iyi kapılar açmasını diliyorum. Size en iyisini diliyorum.',
      'Assalamu Alaikum. I wanted to be transparent with you rather than fade away. I do not see this progressing further, but I truly appreciate your time and wish you every happiness. May Allah bless you.':
          'Selamun Aleyküm. Seninle kaybolmak yerine şeffaf olmak istedim. Bunun daha fazla ilerlediğini görmüyorum, ancak zaman ayırdığınız için gerçekten minnettarım ve size mutluluklar diliyorum. Allah sizden razı olsun.',
