          'کیا آپ شریک حیات کو مالی طور پر فراہم کرنے کے قابل ہیں؟',
      'Are you currently married and looking for an additional spouse?':
          'کیا آپ فی الحال شادی شدہ ہیں اور ایک اضافی شریک حیات کی تلاش میں ہیں؟',
      'Art': 'فن',
      'As soon as possible': 'جتنی جلدی ممکن ہو',
      'Assalamu Alaikum! I came across your profile and was genuinely impressed. May I introduce myself?':
          'السلام علیکم! میں آپ کے پروفائل پر آیا اور حقیقی طور پر متاثر ہوا۔ کیا میں اپنا تعارف کروا سکتا ہوں؟',
      'Assalamu Alaikum! I was really impressed by…':
          'السلام علیکم! میں واقعی اس سے متاثر ہوا تھا…',
      'Assalamu Alaikum. After sincere consideration, I feel we may not be compatible. I hope you find someone truly right for you. May Allah make it easy for you. JazakAllah khair for your time.':
          'السلام علیکم۔ مخلصانہ غور و فکر کے بعد، مجھے لگتا ہے کہ شاید ہم مطابقت نہیں رکھتے۔ مجھے امید ہے کہ آپ کسی کو اپنے لیے صحیح معنوں میں تلاش کریں گے۔ اللہ آپ کے لیے آسانیاں پیدا کرے۔ جزاک اللہ خیر آپ کا وقت۔',
      'Assalamu Alaikum. After thoughtful reflection, I feel this may not be the right match for us. I sincerely wish you all the best and pray that Allah blesses you with a wonderful partner. JazakAllah khair.':
          'السلام علیکم۔ سوچ سمجھ کر سوچنے کے بعد، مجھے لگتا ہے کہ یہ ہمارے لیے صحیح میچ نہیں ہے۔ میں آپ کے لیے نیک خواہشات کا اظہار کرتا ہوں اور دعا کرتا ہوں کہ اللہ آپ کو ایک بہترین ساتھی سے نوازے۔ جزاک اللہ خیر۔',
      'Assalamu Alaikum. I believe we share similar values. Would you be open to getting to know each other?':
          'السلام علیکم۔ مجھے یقین ہے کہ ہم ایک جیسی اقدار کا اشتراک کرتے ہیں۔ کیا آپ ایک دوسرے کو جاننے کے لیے تیار ہوں گے؟',
      'Assalamu Alaikum. I have reflected on our conversations and feel it is best to close this match at this time. I have nothing but respect for you and I make dua that Allah blesses you with the best.':
          'السلام علیکم۔ میں نے اپنی بات چیت پر غور کیا ہے اور محسوس کیا ہے کہ اس وقت اس میچ کو بند کرنا ہی بہتر ہے۔ میرے پاس آپ کے احترام کے سوا کچھ نہیں ہے اور میں دعا کرتا ہوں کہ اللہ آپ کو بہترین سے نوازے۔',
      'Assalamu Alaikum. I wanted to be honest and respectful with you. I do not think we are the right match, but I pray that Allah opens better doors for you. Wishing you all the best.':
          'السلام علیکم۔ میں آپ کے ساتھ ایماندار اور عزت دار بننا چاہتا تھا۔ مجھے نہیں لگتا کہ ہم صحیح میچ ہیں، لیکن میری دعا ہے کہ اللہ آپ کے لیے بہتر دروازے کھولے۔ آپ کے لیے نیک خواہشات۔',
